import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {

    public static void main(String[] args) throws Exception {
        // Generate a private key
        KeyPairGenerator kpg = KeyPairGenerator.getInstance("RSA");
        kpg.initialize(2048);
        PrivateKey privateKey = kpg.generatePrivate();

        // Get the public key from the private key
        PublicKey publicKey = getPublicKey(privateKey.getPublic());

        System.out.println("Public Key:");
        printPublicKey(publicKey);

        // Generate a message to encrypt
        String message = "Hello, World!";
        byte[] encryptedMessage = encrypt(message, publicKey);

        System.out.println("\nEncrypted Message:");
        printBytes(encryptedMessage);

        // Decrypt the message
        String decryptedMessage = decrypt(encryptedMessage, privateKey);
        System.out.println("\nDecrypted Message: " + decryptedMessage);
    }

    public static PublicKey getPublicKey(PrivateKey privateKey) throws Exception {
        // Get the public key from the private key
        return privateKey.getPublic();
    }

    public static byte[] encrypt(String message, PublicKey publicKey) throws Exception {
        // Create a cipher object using the public key
        Cipher cipher = Cipher.getInstance("RSA-SHA256");
        SecretKeySpec secretKeySpec = new SecretKeySpec(publicKey.getEncoded(), "SHA1");
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
        return cipher.doFinal(message.getBytes(StandardCharsets.UTF_8));
    }

    public static String decrypt(byte[] encryptedMessage, PrivateKey privateKey) throws Exception {
        // Create a cipher object using the private key
        Cipher cipher = Cipher.getInstance("RSA-SHA256");
        SecretKeySpec secretKeySpec = new SecretKeySpec(privateKey.getEncoded(), "SHA1");
        cipher.init(Cipher.DECRYPT_MODE, secretKeySpec);
        return (String) cipher.doFinal(encryptedMessage)._bytes().stream()
                .mapToUnsignedByte().reduce("", (a, b) -> a + b);
    }

    public static void printPublicKey(PublicKey publicKey) throws Exception {
        System.out.println("\nPublic Key:");
        byte[] bytes = publicKey.getEncoded();
        for (byte b : bytes) {
            System.out.print(b + " ");
        }
        System.out.println();
    }

    public static void printBytes(byte[] bytes) throws IOException {
        System.out.println("\nBytes: " + java.util.Base64.getEncoder().encodeToString(bytes));
    }
}
